  FT["SG-H2044"] = {"id":"SG-H2044","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S323-2018?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"所得税（外国收入豁免）（第 2 号）命令 2018","en":"Income Tax (Exemption of Foreign Income) (No. 2) Order 2018","orig":"Income Tax (Exemption of Foreign Income) (No. 2) Order 2018","vi":"Lệnh Thuế thu nhập (Miễn trừ thu nhập từ nước ngoài) (Số 2) 2018","th":"คำสั่งภาษีเงินได้ (การยกเว้นรายได้จากต่างประเทศ) (ฉบับที่ 2) 2018","id":"Perintah Pajak Penghasilan (Pembebasan Penghasilan Luar Negeri) (Nomor 2) 2018","ms":"Perintah Cukai Pendapatan (Pengecualian Pendapatan Asing) (No. 2) 2018"},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S323-2018","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2044-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order is the Income Tax (Exemption of Foreign Income) (No. 2) Order 2018."}},{"id":"SG-H2044-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) Income described in sub-paragraph (2) is exempt from tax.\n(2) Sub-paragraph (1) applies to —\n(a)the income received in Singapore by Lee Rubber Company (Pte) Limited on 2 May 2014, 6 May 2014, 3 June 2014 and 15 September 2014, which totals $77,556,553 and is derived from the sale of oil palms from the following oil palm estates located in Malaysia and owned by Lee Rubber Company (Pte) Limited:\n(i)New Scudai Estate;\n(ii)Scudai Estate;\n(iii)Bakri Estate;\n(iv)Ladang Senai;\n(b)any income received in Singapore by Lee Rubber Company (Pte) Limited on or after 16 September 2014, and derived from the sale of oil palms from the oil palm estates mentioned in sub‑paragraph (a);\n(c)the income of $3,012,818 received in Singapore by Selat (Pte) Limited on 16 October 2014, and derived from the sale of oil palms from the following oil palm estates located in Malaysia and owned by Selat (Pte) Limited:\n(i)Shansi Estate;\n(ii)Sungei Masai Estate; and\n(d)any income received in Singapore by Selat (Pte) Limited on or after 17 October 2014, and derived from the sale of oil palms from the oil palm estates mentioned in sub‑paragraph (c).\n(3) The exemption in sub-paragraph (1) is subject to the conditions specified in paragraph 5 of the letter of approval dated 8 February 2018 issued by the Ministry of Finance and addressed to Ernst & Young Solutions LLP."}}],"pack":"sg-p26","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Exemption of Foreign Income) (No. 2) Order 2018","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
