  FT["SG-H2047"] = {"id":"SG-H2047","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S646-2002?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"所得税（外国所得豁免）（第 3 号）命令 2002","en":"Income Tax (Exemption of Foreign Income) (No. 3) Order 2002","orig":"Income Tax (Exemption of Foreign Income) (No. 3) Order 2002","vi":"Lệnh Thuế thu nhập (Miễn trừ thu nhập từ nước ngoài) (Số 3) 2002","th":"คำสั่งภาษีเงินได้ (การยกเว้นรายได้จากต่างประเทศ) (ฉบับที่ 3) 2002","id":"Perintah Pajak Penghasilan (Pembebasan Penghasilan Luar Negeri) (Nomor 3) 2002","ms":"Perintah Cukai Pendapatan (Pengecualian Pendapatan Asing) (No. 3) 2002"},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S646-2002","completenessNote":"全文，共 3 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2047-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation and commencement"},"text":{"en":"1. This Order may be cited as the Income Tax (Exemption of Foreign Income) (No. 3) Order 2002 and shall be deemed to have come into operation on 18th December 2002."}},{"id":"SG-H2047-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) There shall be exempt from tax the approved income from a company outside Singapore which is received in Singapore by an approved international shipping enterprise, subject to the conditions imposed by the Minister and notified to the approved international shipping enterprise.\n(1A) Income received in Singapore by an approved international shipping enterprise from a partnership outside Singapore, being income that is approved for this sub‑paragraph by the Minister, is exempt from tax, subject to the conditions imposed by the Minister and notified to the approved international shipping enterprise.\n[S 129/2018 wef 19/12/2002]\n(1B) Income received in Singapore by an approved international shipping enterprise from its branch outside Singapore, being income that is approved for this sub‑paragraph by the Minister, is exempt from tax, subject to the conditions imposed by the Minister and notified to the approved international shipping enterprise.\n[S 129/2018 wef 24/02/2015]\n(1C) This paragraph applies only to income received in Singapore that is derived before, or is paid out of income that is derived before, 8 March 2018.\n[S 129/2018 wef 08/03/2018]\n(2) In this paragraph —\n“approved income from a company outside Singapore” means such income from such company outside Singapore as may be approved for the purposes of sub-paragraph (1) by the Minister;\n“approved international shipping enterprise” means a company approved as an international shipping enterprise under section 13F of the Act."}},{"id":"SG-H2047-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Revocation"},"text":{"en":"3. The Income Tax (Exemption of Foreign Income) Order 2001 (G.N. No. S 403/2001) is revoked."}}],"pack":"sg-p26","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Exemption of Foreign Income) (No. 3) Order 2002","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
