  FT["SG-H2077"] = {"id":"SG-H2077","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S360-2015?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":7,"structureMode":"ARTICLE","title":{"zh":"所得税（外国收入豁免）（第 5 号）命令 2015","en":"Income Tax (Exemption of Foreign Income) (No. 5) Order 2015","orig":"Income Tax (Exemption of Foreign Income) (No. 5) Order 2015","vi":"Lệnh Thuế thu nhập (Miễn trừ thu nhập từ nước ngoài) (Số 5) 2015","th":"คำสั่งภาษีเงินได้ (การยกเว้นรายได้จากต่างประเทศ) (ฉบับที่ 5) 2015","id":"Perintah Pajak Penghasilan (Pembebasan Penghasilan Luar Negeri) (Nomor 5) 2015","ms":"Perintah Cukai Pendapatan (Pengecualian Pendapatan Asing) (No. 5) 2015"},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S360-2015","completenessNote":"全文，共 7 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2077-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order may be cited as the Income Tax (Exemption of Foreign Income) (No. 5) Order 2015."}},{"id":"SG-H2077-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption for Tata Chemicals International Pte Ltd"},"text":{"en":"2.—(1) Tata Chemicals International Pte Ltd is granted exemption from tax on the dividends received in Singapore on 11 January 2013 from Gusiute Holdings (UK) Limited, a company incorporated in the United Kingdom.\n(2) The exemption in sub-paragraph (1) is subject to the terms and conditions specified in the letter of approval dated 14 August 2013 addressed to Shanker Iyer Consultants Pte Ltd, the tax agent of Tata Chemicals International Pte Ltd."}},{"id":"SG-H2077-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Exemption for Parkway Life Japan2 Pte Ltd"},"text":{"en":"3.—(1) Parkway Life Japan2 Pte Ltd is granted exemption from tax on the Tokumei-Kumiai distributions received in Singapore on or after 28 April 2014 from Godo Kaisha Tenshi 1 and Godo Kaisha Tenshi 2, companies incorporated in Japan.\n(2) The exemption in sub-paragraph (1) is subject to the terms and conditions specified in the letter of approval dated 29 May 2014 addressed to Parkway Trust Management Limited."}},{"id":"SG-H2077-A4","no":4,"noLabel":{"en":"4."},"heading":{"en":"Exemption for Parkway Life Japan3 Pte Ltd"},"text":{"en":"4.—(1) Parkway Life Japan3 Pte Ltd is granted exemption from tax on the Tokumei-Kumiai distributions received in Singapore on or after 2 August 2013 from Godo Kaisha Healthcare 5, a company incorporated in Japan.\n(2) The exemption in sub-paragraph (1) is subject to the terms and conditions specified in the letter of approval dated 11 October 2013 addressed to Parkway Trust Management Limited."}},{"id":"SG-H2077-A5","no":5,"noLabel":{"en":"5."},"heading":{"en":"Exemption for Parkway Life Japan4 Pte Ltd"},"text":{"en":"5.—(1) Parkway Life Japan4 Pte Ltd is granted exemption from tax on the Tokumei-Kumiai distributions received in Singapore on or after 18 October 2013 from Godo Kaisha Samurai 7 and Godo Kaisha Samurai 8, companies incorporated in Japan.\n(2) The exemption in sub-paragraph (1) is subject to the terms and conditions specified in the letter of approval dated 7 January 2014 addressed to Parkway Trust Management Limited."}},{"id":"SG-H2077-A6","no":6,"noLabel":{"en":"6."},"heading":{"en":"Exemption for Mercuria Asia Group Holdings (Pte) Ltd"},"text":{"en":"6.—(1) Mercuria Asia Group Holdings (Pte) Ltd is granted exemption from tax on the dividends received in Singapore on or after 29 November 2013 from Mercuria Resources Labuan Ltd, a company incorporated in Labuan, Malaysia.\n(2) The exemption in sub-paragraph (1) is subject to the terms and conditions specified in the letter of approval dated 15 August 2014 addressed to Ernst & Young Solutions LLP, the tax agent of Mercuria Asia Group Holdings (Pte) Ltd."}},{"id":"SG-H2077-A7","no":7,"noLabel":{"en":"7."},"heading":{"en":"Exemptions for Keppel DC Real Estate Investment Trust, etc."},"text":{"en":"7.—(1) Keppel DC Real Estate Investment Trust is granted exemption from tax on the following income received in Singapore on or after 10 February 2014:\n(a)dividends and interest from Securus Guernsey 1 Limited and Securus Guernsey 2 Limited, companies incorporated in Guernsey;\n(b)dividends from Boxtel Investments Limited, a company incorporated in the British Virgin Islands;\n(c)dividends from Basis Bay Capital Management Sdn Bhd, a company incorporated in Malaysia.\n(2) Securus C100 Pte Ltd is granted exemption from tax on the dividends and interest received in Singapore on or after 10 February 2014 from Citadel 100 Datacentres Limited, a company incorporated in the Republic of Ireland.\n(3) Securus Netherlands 1 Pte Ltd is granted exemption from tax on the dividends received in Singapore on or after 10 February 2014 from Securus Netherlands B.V., a company incorporated in the Netherlands.\n(4) Securus Netherlands 2 Pte Ltd is granted exemption from tax on the interest received in Singapore on or after 10 February 2014 from Securus Almere B.V., a company incorporated in the Netherlands.\n(5) Securus GVP Pte Ltd is granted exemption from tax on the dividends and interest received in Singapore on or after 10 February 2014 from Greenwich View Place Limited, a company incorporated in Guernsey.\n(6) The exemptions in sub-paragraphs (1) to (5) are subject to the terms and conditions specified in the letter of approval dated 25 November 2014 addressed to KPMG Services Pte Ltd, the tax agent of Keppel DC Real Estate Investment Trust."}}],"pack":"sg-p26","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1818-SG-2467","source":"Income Tax (Exemption of Foreign Income) (No. 5) Order 2015","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
